-- ==============================================================================\n-- STREAMS\n-- ==============================================================================\n-- Streams track changes made to the RAW_DATA tables.\n-- They are consumed by the incremental CLEAN_DATA tasks.\n\nUSE DATABASE MARKETING_CAMP_ANALYSIS;\nUSE SCHEMA RAW_DATA;\n\nCREATE OR REPLACE STREAM CUSTOMERS_STREAM\nON TABLE RAW_DATA.CUSTOMERS;\n\nCREATE OR REPLACE STREAM CUSTOMER_JOURNEY_STREAM\nON TABLE RAW_DATA.CUSTOMER_JOURNEY;\n\nCREATE OR REPLACE STREAM CUSTOMER_REVIEW_STREAM\nON TABLE RAW_DATA.CUSTOMER_REVIEWS;\n\nCREATE OR REPLACE STREAM CUSTOMER_ENGAGEMENT_STREAM\nON TABLE RAW_DATA.CUSTOMERS_ENGAGEMENT;\n\nCREATE OR REPLACE STREAM PRODUCTS_STREAM\nON TABLE RAW_DATA.PRODUCTS;\n\nCREATE OR REPLACE STREAM GEOGRAPHY_STREAM\nON TABLE RAW_DATA.GEOGRAPHY;\n\nSHOW STREAMS;\n